class LRUCache {
  constructor () {
    this.max = 1000
    this.map = new Map()
  }

  get (key) {
    const value = this.map.get(key)
    if (value !== undefined) {
      // refresh recency: delete and re-insert at the end
      this.map.delete(key)
      this.map.set(key, value)
    }
    return value
  }

  delete (key) {
    return this.map.delete(key)
  }

  set (key, value) {
    if (value !== undefined) {
      // refresh recency on update as well
      this.map.delete(key)
      this.map.set(key, value)
      if (this.map.size > this.max) {
        this.map.delete(this.map.keys().next().value)
      }
    }

    return this
  }
}

module.exports = LRUCache
