const parse = require('./parse.js')

const diff = (version1, version2) => {
  const v1 = parse(version1, null, true)
  const v2 = parse(version2, null, true)
  const comparison = v1.compare(v2)

  if (comparison === 0) {
    return null
  }

  const v1Higher = comparison > 0
  const high = v1Higher ? v1 : v2
  const low = v1Higher ? v2 : v1
  const highHasPre = !!high.prerelease.length
  const lowHasPre = !!low.prerelease.length

  // Determine the release type from the main version differences, independent
  // of argument order (we always look at the higher vs lower version).
  let type
  if (high.major !== low.major) {
    type = 'major'
  } else if (high.minor !== low.minor) {
    type = 'minor'
  } else if (high.patch !== low.patch) {
    type = 'patch'
  } else if (highHasPre || lowHasPre) {
    // main versions are identical; this is a prerelease-only change
    if (!lowHasPre) {
      // stepping into a prerelease
      return 'prerelease'
    }
    if (!highHasPre) {
      // stepping out of a prerelease
      if (low.minor === 0 && low.patch === 0) {
        return 'major'
      } else if (low.minor !== 0 && low.patch === 0) {
        return 'minor'
      }
      return 'patch'
    }
    // both are prereleases of the same main version
    return 'prerelease'
  } else {
    // identical precedence but comparison was not 0 (should not happen)
    return null
  }

  // add the `pre` prefix when stepping into a prerelease
  return (highHasPre ? 'pre' : '') + type
}

