class LRUCache {
  constructor () {
    this.max = 1000
    this.map = new Map()
  }

  get (key) {
    const value = this.map.get(key)
    if (value !== undefined) {
      this.map.delete(key)
      this.map.set(key, value)
    }

    return value
  }

  delete (key) {
    return this.map.delete(key)
  }

  set (key, value) {
    if (value !== undefined) {
      if (this.map.has(key)) {
        this.map.delete(key)
      } else if (this.map.size >= this.max) {
        this.map.delete(this.map.keys().next().value)
      }

      this.map.set(key, value)
    }

    return this
  }
}

